function computeDayHasAvailability(dayHours, dateStr, allAppointments, allBlocks, serviceDuration, standardInterval, now) {
  const dayStart = new Date(dateStr + 'T00:00:00')
  const dayEnd = new Date(dateStr + 'T23:59:59')
  const appointments = allAppointments.filter(apt => {
    const t = new Date(apt.start_time)
    return t >= dayStart && t <= dayEnd
  })
  const blocks = allBlocks.filter(b => {
    const s = new Date(b.start_datetime)
    const e = new Date(b.end_datetime)
    return e >= dayStart && s <= dayEnd
  })
  const [startH, startM] = dayHours.start_time.split(':').map(Number)
  const [endH, endM] = dayHours.end_time.split(':').map(Number)
  const workStart = startH * 60 + startM
  const workEnd = endH * 60 + endM

  const hasConflictAt = (start, end) => {
    if (dayHours.break_start_time && dayHours.break_end_time) {
      const [bsH, bsM] = dayHours.break_start_time.split(':').map(Number)
      const [beH, beM] = dayHours.break_end_time.split(':').map(Number)
      const breakStart = bsH * 60 + bsM, breakEnd = beH * 60 + beM
      const sm = start.getHours() * 60 + start.getMinutes()
      const em = end.getHours() * 60 + end.getMinutes()
      if (sm < breakEnd && em > breakStart) return true
    }
    const hasApt = appointments.some(a => start < new Date(a.end_time) && end > new Date(a.start_time))
    const hasBlk = blocks.some(b => start < new Date(b.end_datetime) && end > new Date(b.start_datetime))
    return hasApt || hasBlk
  }

  const segments = []
  if (dayHours.break_start_time && dayHours.break_end_time) {
    const [bsH, bsM] = dayHours.break_start_time.split(':').map(Number)
    const [beH, beM] = dayHours.break_end_time.split(':').map(Number)
    segments.push([workStart, bsH * 60 + bsM])
    segments.push([beH * 60 + beM, workEnd])
  } else {
    segments.push([workStart, workEnd])
  }

  for (const [segStart, segEnd] of segments) {
    for (let minutes = segStart; minutes + serviceDuration <= segEnd; minutes += standardInterval) {
      const slotStart = new Date(dateStr + 'T00:00:00')
      slotStart.setHours(Math.floor(minutes / 60), minutes % 60, 0, 0)
      const slotEnd = new Date(slotStart)
      slotEnd.setMinutes(slotEnd.getMinutes() + serviceDuration)
      if (slotStart <= now) continue
      if (hasConflictAt(slotStart, slotEnd)) continue
      return { available: true, time: `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}` }
    }
  }
  if (serviceDuration < standardInterval) {
    for (const apt of appointments) {
      const aptStart = new Date(apt.start_time)
      const aptEnd = new Date(apt.end_time)
      const aptDuration = (aptEnd - aptStart) / 60000
      if (aptDuration < standardInterval) {
        const gapStart = new Date(aptEnd)
        const gapEnd = new Date(gapStart)
        gapEnd.setMinutes(gapEnd.getMinutes() + serviceDuration)
        const gapMinutes = gapStart.getHours() * 60 + gapStart.getMinutes()
        if (gapMinutes + serviceDuration > workEnd) continue
        if (gapStart <= now) continue
        if (hasConflictAt(gapStart, gapEnd)) continue
        return { available: true, time: 'gap' }
      }
    }
  }
  return { available: false }
}

const barbers = await sb('barbers?select=id,name')
console.log('BARBERS:', JSON.stringify(barbers))

for (const barber of barbers) {
  const barberId = barber.id
  const workingHours = await sb(`working_hours?select=*&barber_id=eq.${barberId}`)
  const now = new Date('2026-09-19T10:00:00')
  const rangeStart = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const rangeEnd = new Date(rangeStart)
  rangeEnd.setDate(rangeEnd.getDate() + 30)

  const appointments = await sb(`appointments?select=start_time,end_time&barber_id=eq.${barberId}&start_time=gte.${rangeStart.toISOString()}&start_time=lt.${rangeEnd.toISOString()}&status=neq.cancelled`)
  const blocks = await sb(`blocked_times?select=start_datetime,end_datetime&barber_id=eq.${barberId}&end_datetime=gte.${rangeStart.toISOString()}&start_datetime=lt.${rangeEnd.toISOString()}`)

  console.log(`\n=== Barber ${barber.name} (${barberId}) ===`)
  console.log(`Appointments in range: ${appointments.length}, Blocks: ${blocks.length}`)

  for (let i = 0; i < 30; i++) {
    const date = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i)
    const dateStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
    let dow = date.getDay() - 1
    if (dow < 0) dow = 6
    const dayHours = workingHours.find(h => h.day_of_week === dow)
    if (!dayHours || !dayHours.is_working) continue
    const result45 = computeDayHasAvailability(dayHours, dateStr, appointments, blocks, 45, 45, now)
    console.log(`${dateStr} (dow=${dow}) hours=${dayHours.start_time}-${dayHours.end_time} break=${dayHours.break_start_time}-${dayHours.break_end_time} => 45min: ${JSON.stringify(result45)}`)
  }
}

